FILES['clients/models.py'] = 'from datetime import date\nfrom django.db import models\n\n\nclass Owner(models.Model):\n    first_name = models.CharField(max_length=100, verbose_name="Imie")\n    last_name = models.CharField(max_length=100, verbose_name="Nazwisko")\n    phone = models.CharField(max_length=30, verbose_name="Telefon")\n    email = models.EmailField(blank=True, verbose_name="Email")\n    notes = models.TextField(blank=True, verbose_name="Notatki")\n    is_active = models.BooleanField(default=True, verbose_name="Aktywny")\n\n    secondary_contact_name = models.CharField(\n        max_length=100, blank=True, verbose_name="Kontakt zastepczy - imie i nazwisko"\n    )\n    secondary_contact_phone = models.CharField(\n        max_length=30, blank=True, verbose_name="Kontakt zastepczy - telefon"\n    )\n\n    rodo_consent = models.BooleanField(\n        default=False, verbose_name="Zgoda na przetwarzanie danych osobowych (RODO)"\n    )\n    rodo_consent_date = models.DateField(\n        null=True, blank=True, verbose_name="Data udzielenia zgody RODO"\n    )\n    photo_consent = models.BooleanField(\n        default=False, verbose_name="Zgoda na wykorzystanie zdjec psa (np. social media)"\n    )\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'last_name\', \'first_name\']\n        verbose_name = "Wlasciciel"\n        verbose_name_plural = "Wlasciciele"\n\n    def __str__(self):\n        return self.full_name\n\n    @property\n    def full_name(self):\n        return f"{self.first_name} {self.last_name}"\n\n    def active_dogs(self):\n        return self.dogs.filter(is_active=True)\n\n    def save(self, *args, **kwargs):\n        if self.rodo_consent and not self.rodo_consent_date:\n            self.rodo_consent_date = date.today()\n        if not self.rodo_consent:\n            self.rodo_consent_date = None\n        super().save(*args, **kwargs)\n\n\nclass Dog(models.Model):\n    SEX_MALE = \'M\'\n    SEX_FEMALE = \'F\'\n    SEX_CHOICES = [\n        (SEX_MALE, \'Pies (samiec)\'),\n        (SEX_FEMALE, \'Suczka (samica)\'),\n    ]\n\n    STATUS_ACTIVE = \'active\'\n    STATUS_PAUSED = \'paused\'\n    TRAINING_STATUS_CHOICES = [\n        (STATUS_ACTIVE, \'Aktywny\'),\n        (STATUS_PAUSED, \'Wstrzymany (tymczasowo)\'),\n    ]\n\n    owner = models.ForeignKey(\n        Owner, related_name=\'dogs\', on_delete=models.CASCADE, verbose_name="Wlasciciel"\n    )\n    name = models.CharField(max_length=100, verbose_name="Imie psa")\n    breed = models.CharField(max_length=100, blank=True, verbose_name="Rasa")\n    sex = models.CharField(max_length=1, choices=SEX_CHOICES, blank=True, verbose_name="Plec")\n    birth_date = models.DateField(null=True, blank=True, verbose_name="Data urodzenia")\n    weight_kg = models.DecimalField(\n        max_digits=5, decimal_places=2, null=True, blank=True, verbose_name="Waga (kg)"\n    )\n    health_notes = models.TextField(blank=True, verbose_name="Informacje zdrowotne / przeciwwskazania")\n    trainer_notes = models.TextField(blank=True, verbose_name="Notatki trenera")\n    photo = models.ImageField(upload_to=\'dogs/\', blank=True, null=True, verbose_name="Zdjecie")\n\n    training_status = models.CharField(\n        max_length=10, choices=TRAINING_STATUS_CHOICES, default=STATUS_ACTIVE,\n        verbose_name="Status treningowy"\n    )\n    is_active = models.BooleanField(default=True, verbose_name="Aktywny (archiwizacja)")\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    MAX_DIMENSION = 1600\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Pies"\n        verbose_name_plural = "Psy"\n\n    def __str__(self):\n        return self.name\n\n    def get_age_display(self):\n        if not self.birth_date:\n            return None\n        today = date.today()\n        if self.birth_date > today:\n            return None\n\n        years = today.year - self.birth_date.year - (\n            (today.month, today.day) < (self.birth_date.month, self.birth_date.day)\n        )\n        months = (today.year - self.birth_date.year) * 12 + (today.month - self.birth_date.month)\n        if today.day < self.birth_date.day:\n            months -= 1\n\n        if years < 1:\n            m = max(months, 0)\n            if m == 0:\n                return "poniżej miesiąca"\n            elif m == 1:\n                return f"{m} miesiąc"\n            elif 2 <= m <= 4:\n                return f"{m} miesiące"\n            else:\n                return f"{m} miesięcy"\n        else:\n            y = years\n            if y == 1:\n                return f"{y} rok"\n            elif 2 <= (y % 10) <= 4 and not (11 <= (y % 100) <= 14):\n                return f"{y} lata"\n            else:\n                return f"{y} lat"\n\n    def save(self, *args, **kwargs):\n        super().save(*args, **kwargs)\n        self._resize_photo_if_needed()\n\n    def _resize_photo_if_needed(self):\n        try:\n            from PIL import Image as PILImage\n            if not self.photo or not self.photo.name:\n                return\n            path = self.photo.path\n            with PILImage.open(path) as img:\n                width, height = img.size\n                if width <= self.MAX_DIMENSION and height <= self.MAX_DIMENSION:\n                    return\n                img = img.convert(\'RGB\') if img.mode in (\'RGBA\', \'P\') else img\n                img.thumbnail((self.MAX_DIMENSION, self.MAX_DIMENSION), PILImage.LANCZOS)\n                save_kwargs = {\'optimize\': True}\n                fmt = (img.format or \'JPEG\')\n                if path.lower().endswith((\'.jpg\', \'.jpeg\')):\n                    save_kwargs[\'quality\'] = 85\n                    fmt = \'JPEG\'\n                img.save(path, format=fmt, **save_kwargs)\n        except Exception:\n            pass\n'
FILES['clients/forms.py'] = "import re\nfrom django import forms\nfrom django.core.exceptions import ValidationError\nfrom .models import Owner, Dog\n\nMAX_PHOTO_SIZE_MB = 5\n\n\nclass OwnerForm(forms.ModelForm):\n    class Meta:\n        model = Owner\n        fields = [\n            'first_name', 'last_name', 'phone', 'email', 'notes',\n            'secondary_contact_name', 'secondary_contact_phone',\n            'rodo_consent', 'photo_consent',\n        ]\n        widgets = {\n            'first_name': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'Imie'}),\n            'last_name': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'Nazwisko'}),\n            'phone': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'np. 600 123 456'}),\n            'email': forms.EmailInput(attrs={'class': 'form-control', 'placeholder': 'np. jan@example.com'}),\n            'notes': forms.Textarea(attrs={'class': 'form-control', 'rows': 3, 'placeholder': 'Notatki, np. preferowany kontakt...'}),\n            'secondary_contact_name': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'np. partner/partnerka, dziecko'}),\n            'secondary_contact_phone': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'np. 600 999 888'}),\n            'rodo_consent': forms.CheckboxInput(attrs={'class': 'form-check-input'}),\n            'photo_consent': forms.CheckboxInput(attrs={'class': 'form-check-input'}),\n        }\n\n    def clean_first_name(self):\n        value = self.cleaned_data.get('first_name', '').strip()\n        if len(value) < 2:\n            raise ValidationError('Imie musi miec przynajmniej 2 znaki.')\n        return value\n\n    def clean_last_name(self):\n        value = self.cleaned_data.get('last_name', '').strip()\n        if len(value) < 2:\n            raise ValidationError('Nazwisko musi miec przynajmniej 2 znaki.')\n        return value\n\n    def is_phone_suspicious(self):\n        phone = self.cleaned_data.get('phone', '')\n        digits_only = re.sub(r'\\D', '', phone or '')\n        return len(digits_only) not in (9, 11, 12)\n\n\nclass DogForm(forms.ModelForm):\n    class Meta:\n        model = Dog\n        fields = [\n            'owner', 'name', 'breed', 'sex', 'birth_date', 'weight_kg',\n            'health_notes', 'trainer_notes', 'photo', 'training_status',\n        ]\n        widgets = {\n            'owner': forms.Select(attrs={'class': 'form-select'}),\n            'name': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'Imie psa'}),\n            'breed': forms.TextInput(attrs={'class': 'form-control', 'placeholder': 'np. Border Collie'}),\n            'sex': forms.Select(attrs={'class': 'form-select'}),\n            'birth_date': forms.DateInput(attrs={'class': 'form-control', 'type': 'date'}),\n            'weight_kg': forms.NumberInput(attrs={'class': 'form-control', 'step': '0.1', 'placeholder': 'np. 22.5'}),\n            'health_notes': forms.Textarea(attrs={'class': 'form-control', 'rows': 3, 'placeholder': 'Kontuzje, przeciwwskazania...'}),\n            'trainer_notes': forms.Textarea(attrs={'class': 'form-control', 'rows': 3, 'placeholder': 'Prywatne notatki trenera...'}),\n            'photo': forms.ClearableFileInput(attrs={'class': 'form-control'}),\n            'training_status': forms.Select(attrs={'class': 'form-select'}),\n        }\n\n    def __init__(self, *args, fixed_owner=None, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.fields['owner'].queryset = Owner.objects.filter(is_active=True)\n        if fixed_owner is not None:\n            self.fields['owner'].initial = fixed_owner.pk\n            self.fields['owner'].widget = forms.HiddenInput()\n            self.fields['owner'].required = False\n\n    def clean_name(self):\n        value = self.cleaned_data.get('name', '').strip()\n        if len(value) < 2:\n            raise ValidationError('Imie psa musi miec przynajmniej 2 znaki.')\n        return value\n\n    def clean_photo(self):\n        photo = self.cleaned_data.get('photo')\n        if photo and hasattr(photo, 'size'):\n            if photo.size > MAX_PHOTO_SIZE_MB * 1024 * 1024:\n                raise ValidationError(f'Zdjecie jest za duze (max {MAX_PHOTO_SIZE_MB}MB).')\n            content_type = getattr(photo, 'content_type', None)\n            if content_type and not content_type.startswith('image/'):\n                raise ValidationError('Plik musi byc obrazem.')\n        return photo\n"
FILES['clients/views.py'] = 'import csv\nfrom django.shortcuts import render, redirect, get_object_or_404\nfrom django.contrib import messages\nfrom django.contrib.auth.decorators import login_required\nfrom django.db.models import Q\nfrom django.core.paginator import Paginator\nfrom django.http import HttpResponse\nfrom .models import Owner, Dog\nfrom .forms import OwnerForm, DogForm\n\nCLIENTS_PER_PAGE = 25\n\nPHONE_WARNING_MSG = \'Numer telefonu moze byc niepoprawny - sprawdz, czy to nie pomylka. Zapisano mimo to.\'\n\n\n# ============ OWNER ============\n\n@login_required\ndef owner_list(request):\n    owners = Owner.objects.filter(is_active=True).prefetch_related(\'dogs\')\n\n    search_query = request.GET.get(\'q\', \'\').strip()\n    if search_query:\n        owners = owners.filter(\n            Q(first_name__icontains=search_query) |\n            Q(last_name__icontains=search_query) |\n            Q(phone__icontains=search_query) |\n            Q(email__icontains=search_query) |\n            Q(dogs__name__icontains=search_query)\n        ).distinct()\n\n    paginator = Paginator(owners, CLIENTS_PER_PAGE)\n    page_obj = paginator.get_page(request.GET.get(\'page\'))\n\n    stats = {\n        \'owners_count\': Owner.objects.filter(is_active=True).count(),\n        \'dogs_count\': Dog.objects.filter(is_active=True).count(),\n    }\n\n    return render(request, \'clients/owner_list.html\', {\n        \'page_obj\': page_obj,\n        \'search_query\': search_query,\n        \'stats\': stats,\n    })\n\n\n@login_required\ndef owner_create(request):\n    if request.method == \'POST\':\n        form = OwnerForm(request.POST)\n        if form.is_valid():\n            owner = form.save()\n            if form.is_phone_suspicious():\n                messages.warning(request, PHONE_WARNING_MSG)\n            messages.success(request, \'Wlasciciel zostal dodany.\')\n            return redirect(\'owner_detail\', pk=owner.pk)\n    else:\n        form = OwnerForm()\n    return render(request, \'clients/owner_form.html\', {\n        \'form\': form,\n        \'title\': \'Dodaj klienta\',\n    })\n\n\n@login_required\ndef owner_update(request, pk):\n    owner = get_object_or_404(Owner, pk=pk)\n    if request.method == \'POST\':\n        form = OwnerForm(request.POST, instance=owner)\n        if form.is_valid():\n            form.save()\n            if form.is_phone_suspicious():\n                messages.warning(request, PHONE_WARNING_MSG)\n            messages.success(request, \'Dane wlasciciela zostaly zaktualizowane.\')\n            return redirect(\'owner_detail\', pk=owner.pk)\n    else:\n        form = OwnerForm(instance=owner)\n    return render(request, \'clients/owner_form.html\', {\n        \'form\': form,\n        \'title\': \'Edytuj klienta\',\n        \'owner\': owner,\n    })\n\n\n@login_required\ndef owner_detail(request, pk):\n    owner = get_object_or_404(Owner, pk=pk)\n    return render(request, \'clients/owner_detail.html\', {\n        \'owner\': owner,\n        \'dogs\': owner.dogs.filter(is_active=True),\n    })\n\n\n@login_required\ndef owner_delete(request, pk):\n    owner = get_object_or_404(Owner, pk=pk)\n    active_dogs_count = owner.dogs.filter(is_active=True).count()\n    if request.method == \'POST\':\n        owner.is_active = False\n        owner.save()\n        messages.success(request, \'Klient zostal przeniesiony do archiwum.\')\n        return redirect(\'owner_list\')\n    return render(request, \'clients/owner_confirm_delete.html\', {\n        \'owner\': owner,\n        \'active_dogs_count\': active_dogs_count,\n    })\n\n\n@login_required\ndef owner_archived_list(request):\n    owners = Owner.objects.filter(is_active=False).order_by(\'-updated_at\')\n    return render(request, \'clients/owner_archived_list.html\', {\'owners\': owners})\n\n\n@login_required\ndef owner_restore(request, pk):\n    owner = get_object_or_404(Owner, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        owner.is_active = True\n        owner.save()\n        messages.success(request, \'Klient zostal przywrocony.\')\n    return redirect(\'owner_archived_list\')\n\n\n@login_required\ndef owner_delete_permanent(request, pk):\n    owner = get_object_or_404(Owner, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        owner.delete()\n        messages.success(request, \'Klient zostal usuniety na zawsze (wraz z psami).\')\n    return redirect(\'owner_archived_list\')\n\n\n@login_required\ndef owner_export_csv(request):\n    """Eksport aktywnych klientow do CSV (np. do uzycia offline na telefonie)."""\n    response = HttpResponse(content_type=\'text/csv; charset=utf-8-sig\')\n    response[\'Content-Disposition\'] = \'attachment; filename="klienci.csv"\'\n    writer = csv.writer(response, delimiter=\';\')\n    writer.writerow([\n        \'Imie\', \'Nazwisko\', \'Telefon\', \'Email\', \'Kontakt zastepczy\', \'Telefon zastepczy\',\n        \'Zgoda RODO\', \'Zgoda na zdjecia\', \'Psy\', \'Notatki\',\n    ])\n    owners = Owner.objects.filter(is_active=True).prefetch_related(\'dogs\')\n    for owner in owners:\n        dog_names = \', \'.join(d.name for d in owner.dogs.filter(is_active=True))\n        writer.writerow([\n            owner.first_name, owner.last_name, owner.phone, owner.email,\n            owner.secondary_contact_name, owner.secondary_contact_phone,\n            \'Tak\' if owner.rodo_consent else \'Nie\',\n            \'Tak\' if owner.photo_consent else \'Nie\',\n            dog_names, owner.notes,\n        ])\n    return response\n\n\n# ============ DOG ============\n\n@login_required\ndef dog_list(request):\n    dogs = Dog.objects.filter(is_active=True).select_related(\'owner\')\n\n    search_query = request.GET.get(\'q\', \'\').strip()\n    if search_query:\n        dogs = dogs.filter(\n            Q(name__icontains=search_query) |\n            Q(breed__icontains=search_query) |\n            Q(owner__first_name__icontains=search_query) |\n            Q(owner__last_name__icontains=search_query)\n        ).distinct()\n\n    paginator = Paginator(dogs, CLIENTS_PER_PAGE)\n    page_obj = paginator.get_page(request.GET.get(\'page\'))\n\n    return render(request, \'clients/dog_list.html\', {\n        \'page_obj\': page_obj,\n        \'search_query\': search_query,\n    })\n\n\n@login_required\ndef dog_create(request, owner_pk=None):\n    fixed_owner = None\n    if owner_pk:\n        fixed_owner = get_object_or_404(Owner, pk=owner_pk)\n\n    if request.method == \'POST\':\n        form = DogForm(request.POST, request.FILES, fixed_owner=fixed_owner)\n        if form.is_valid():\n            dog = form.save(commit=False)\n            if fixed_owner:\n                dog.owner = fixed_owner\n            dog.save()\n            messages.success(request, f\'Pies {dog.name} zostal dodany.\')\n            if fixed_owner:\n                return redirect(\'owner_detail\', pk=fixed_owner.pk)\n            return redirect(\'dog_detail\', pk=dog.pk)\n    else:\n        form = DogForm(fixed_owner=fixed_owner)\n\n    return render(request, \'clients/dog_form.html\', {\n        \'form\': form,\n        \'title\': \'Dodaj psa\',\n        \'fixed_owner\': fixed_owner,\n    })\n\n\n@login_required\ndef dog_update(request, pk):\n    dog = get_object_or_404(Dog, pk=pk)\n    if request.method == \'POST\':\n        form = DogForm(request.POST, request.FILES, instance=dog)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Dane psa zostaly zaktualizowane.\')\n            return redirect(\'dog_detail\', pk=dog.pk)\n    else:\n        form = DogForm(instance=dog)\n    return render(request, \'clients/dog_form.html\', {\n        \'form\': form,\n        \'title\': \'Edytuj psa\',\n        \'dog\': dog,\n    })\n\n\n@login_required\ndef dog_detail(request, pk):\n    dog = get_object_or_404(Dog, pk=pk)\n    return render(request, \'clients/dog_detail.html\', {\'dog\': dog})\n\n\n@login_required\ndef dog_delete(request, pk):\n    dog = get_object_or_404(Dog, pk=pk)\n    if request.method == \'POST\':\n        dog.is_active = False\n        dog.save()\n        messages.success(request, \'Pies zostal przeniesiony do archiwum.\')\n        return redirect(\'owner_detail\', pk=dog.owner.pk)\n    return render(request, \'clients/dog_confirm_delete.html\', {\'dog\': dog})\n\n\n@login_required\ndef dog_archived_list(request):\n    dogs = Dog.objects.filter(is_active=False).select_related(\'owner\').order_by(\'-updated_at\')\n    return render(request, \'clients/dog_archived_list.html\', {\'dogs\': dogs})\n\n\n@login_required\ndef dog_restore(request, pk):\n    dog = get_object_or_404(Dog, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        dog.is_active = True\n        dog.save()\n        messages.success(request, \'Pies zostal przywrocony.\')\n    return redirect(\'dog_archived_list\')\n\n\n@login_required\ndef dog_delete_permanent(request, pk):\n    dog = get_object_or_404(Dog, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        dog.delete()\n        messages.success(request, \'Pies zostal usuniety na zawsze.\')\n    return redirect(\'dog_archived_list\')\n\n\n@login_required\ndef dog_toggle_training_status(request, pk):\n    """Szybkie przelaczenie statusu Aktywny <-> Wstrzymany (bez archiwizacji)."""\n    dog = get_object_or_404(Dog, pk=pk)\n    if request.method == \'POST\':\n        if dog.training_status == Dog.STATUS_ACTIVE:\n            dog.training_status = Dog.STATUS_PAUSED\n            messages.success(request, f\'Trening {dog.name} zostal wstrzymany.\')\n        else:\n            dog.training_status = Dog.STATUS_ACTIVE\n            messages.success(request, f\'Trening {dog.name} zostal przywrocony (aktywny).\')\n        dog.save()\n    return redirect(request.META.get(\'HTTP_REFERER\', \'dog_list\'))\n\n\n@login_required\ndef dog_export_csv(request):\n    """Eksport aktywnych psow do CSV."""\n    response = HttpResponse(content_type=\'text/csv; charset=utf-8-sig\')\n    response[\'Content-Disposition\'] = \'attachment; filename="psy.csv"\'\n    writer = csv.writer(response, delimiter=\';\')\n    writer.writerow([\n        \'Imie psa\', \'Rasa\', \'Plec\', \'Wiek\', \'Waga (kg)\', \'Status treningowy\',\n        \'Wlasciciel\', \'Telefon wlasciciela\', \'Informacje zdrowotne\',\n    ])\n    dogs = Dog.objects.filter(is_active=True).select_related(\'owner\')\n    for dog in dogs:\n        writer.writerow([\n            dog.name, dog.breed, dog.get_sex_display() if dog.sex else \'\',\n            dog.get_age_display() or \'\', dog.weight_kg or \'\',\n            dog.get_training_status_display(),\n            dog.owner.full_name, dog.owner.phone, dog.health_notes,\n        ])\n    return response\n'
FILES['clients/urls.py'] = "from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    # Wlasciciele\n    path('clients/', views.owner_list, name='owner_list'),\n    path('clients/add/', views.owner_create, name='owner_create'),\n    path('clients/export/', views.owner_export_csv, name='owner_export_csv'),\n    path('clients/archived/', views.owner_archived_list, name='owner_archived_list'),\n    path('clients/<int:pk>/', views.owner_detail, name='owner_detail'),\n    path('clients/<int:pk>/edit/', views.owner_update, name='owner_update'),\n    path('clients/<int:pk>/delete/', views.owner_delete, name='owner_delete'),\n    path('clients/<int:pk>/restore/', views.owner_restore, name='owner_restore'),\n    path('clients/<int:pk>/delete-permanent/', views.owner_delete_permanent, name='owner_delete_permanent'),\n    path('clients/<int:owner_pk>/dogs/add/', views.dog_create, name='dog_create_for_owner'),\n\n    # Psy\n    path('dogs/', views.dog_list, name='dog_list'),\n    path('dogs/add/', views.dog_create, name='dog_create'),\n    path('dogs/export/', views.dog_export_csv, name='dog_export_csv'),\n    path('dogs/archived/', views.dog_archived_list, name='dog_archived_list'),\n    path('dogs/<int:pk>/', views.dog_detail, name='dog_detail'),\n    path('dogs/<int:pk>/edit/', views.dog_update, name='dog_update'),\n    path('dogs/<int:pk>/delete/', views.dog_delete, name='dog_delete'),\n    path('dogs/<int:pk>/restore/', views.dog_restore, name='dog_restore'),\n    path('dogs/<int:pk>/delete-permanent/', views.dog_delete_permanent, name='dog_delete_permanent'),\n    path('dogs/<int:pk>/toggle-status/', views.dog_toggle_training_status, name='dog_toggle_training_status'),\n]\n"
FILES['clients/admin.py'] = 'from django.contrib import admin\nfrom .models import Owner, Dog\n\n\nclass DogInline(admin.TabularInline):\n    model = Dog\n    extra = 1\n    fields = (\'name\', \'breed\', \'sex\', \'birth_date\', \'weight_kg\', \'training_status\', \'is_active\')\n\n\n@admin.register(Owner)\nclass OwnerAdmin(admin.ModelAdmin):\n    list_display = (\'full_name\', \'phone\', \'email\', \'rodo_consent\', \'is_active\', \'created_at\')\n    list_filter = (\'is_active\', \'rodo_consent\', \'photo_consent\')\n    search_fields = (\'first_name\', \'last_name\', \'phone\', \'email\')\n    inlines = [DogInline]\n    actions = [\'make_active\', \'make_archived\']\n\n    def make_active(self, request, queryset):\n        updated = queryset.update(is_active=True)\n        self.message_user(request, f"Przywrocono {updated} wlascicieli.")\n    make_active.short_description = "Przywroc zaznaczonych"\n\n    def make_archived(self, request, queryset):\n        updated = queryset.update(is_active=False)\n        self.message_user(request, f"Zarchiwizowano {updated} wlascicieli.")\n    make_archived.short_description = "Zarchiwizuj zaznaczonych"\n\n\n@admin.register(Dog)\nclass DogAdmin(admin.ModelAdmin):\n    list_display = (\'name\', \'owner\', \'breed\', \'sex\', \'training_status\', \'is_active\', \'created_at\')\n    list_filter = (\'is_active\', \'training_status\', \'sex\', \'breed\')\n    search_fields = (\'name\', \'breed\', \'owner__first_name\', \'owner__last_name\')\n'
FILES['clients/templates/clients/owner_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Klienci{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1><i class="bi bi-people" style="color: #D4AF37;"></i> Klienci</h1>\n    <div>\n        <a href="{% url \'owner_export_csv\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-download"></i> Eksport CSV\n        </a>\n        <a href="{% url \'owner_archived_list\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-archive"></i> Archiwum\n        </a>\n        <a href="{% url \'dog_list\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-list-ul"></i> Wszystkie psy\n        </a>\n        <a href="{% url \'owner_create\' %}" class="btn btn-primary">\n            <i class="bi bi-plus-lg"></i> Dodaj klienta\n        </a>\n    </div>\n</div>\n\n<div class="stats-panel mb-4">\n    <div class="stat-box">\n        <span class="stat-number">{{ stats.owners_count }}</span>\n        <span class="stat-label">Aktywnych wlascicieli</span>\n    </div>\n    <div class="stat-box">\n        <span class="stat-number">{{ stats.dogs_count }}</span>\n        <span class="stat-label">Aktywnych psow</span>\n    </div>\n</div>\n\n<div class="search-bar">\n    <form method="get" class="row g-2 align-items-center">\n        <div class="col-md-10">\n            <div class="input-group">\n                <span class="input-group-text bg-white border-0"><i class="bi bi-search"></i></span>\n                <input type="text" name="q" class="form-control border-0" placeholder="Szukaj po imieniu, nazwisku, telefonie, emailu lub imieniu psa..." value="{{ search_query }}">\n            </div>\n        </div>\n        <div class="col-md-2">\n            <button type="submit" class="btn btn-primary w-100"><i class="bi bi-funnel"></i> Szukaj</button>\n        </div>\n    </form>\n    {% if search_query %}\n        <div class="mt-2">\n            <a href="{% url \'owner_list\' %}" class="btn btn-sm btn-outline-secondary">\n                <i class="bi bi-x-circle"></i> Wyczysc\n            </a>\n        </div>\n    {% endif %}\n</div>\n\n<div class="row">\n    {% for owner in page_obj %}\n    <div class="col-md-4 mb-4">\n        <div class="card exercise-card">\n            <div class="card-body">\n                <h5 class="card-title">\n                    <i class="bi bi-person-circle"></i> {{ owner.full_name }}\n                    {% if not owner.rodo_consent %}\n                        <i class="bi bi-exclamation-triangle-fill text-warning" title="Brak zgody RODO" style="font-size: 0.8rem;"></i>\n                    {% endif %}\n                </h5>\n                <p class="card-text text-muted small mb-1">\n                    <i class="bi bi-telephone"></i> <a href="tel:{{ owner.phone }}">{{ owner.phone }}</a>\n                </p>\n                {% if owner.email %}\n                <p class="card-text text-muted small mb-1">\n                    <i class="bi bi-envelope"></i> <a href="mailto:{{ owner.email }}">{{ owner.email }}</a>\n                </p>\n                {% endif %}\n                <div class="mb-2">\n                    {% for dog in owner.dogs.all %}\n                        {% if dog.is_active %}\n                        <span class="badge badge-muscle"><i class="bi bi-suit-heart-fill"></i> {{ dog.name }}</span>\n                        {% endif %}\n                    {% endfor %}\n                </div>\n            </div>\n            <div class="card-footer bg-white border-0 pb-3">\n                <a href="{% url \'owner_detail\' owner.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-eye"></i> Szczegoly\n                </a>\n                <a href="{% url \'owner_update\' owner.pk %}" class="btn btn-sm btn-outline-secondary">\n                    <i class="bi bi-pencil"></i>\n                </a>\n                <a href="{% url \'owner_delete\' owner.pk %}" class="btn btn-sm btn-outline-danger">\n                    <i class="bi bi-archive"></i>\n                </a>\n            </div>\n        </div>\n    </div>\n    {% empty %}\n    <div class="col-12">\n        <div class="empty-state">\n            <i class="bi bi-inbox"></i>\n            <p class="mb-3">\n                {% if search_query %}\n                    Nie znaleziono klientow spelniajacych kryteria.\n                {% else %}\n                    Brak klientow w bazie. Dodaj pierwszego!\n                {% endif %}\n            </p>\n            <a href="{% url \'owner_create\' %}" class="btn btn-primary">\n                <i class="bi bi-plus-lg"></i> Dodaj klienta\n            </a>\n        </div>\n    </div>\n    {% endfor %}\n</div>\n\n{% if page_obj.paginator.num_pages > 1 %}\n<nav class="d-flex justify-content-center mt-4">\n    <ul class="pagination">\n        {% if page_obj.has_previous %}\n            <li class="page-item"><a class="page-link" href="?page=1">&laquo;&laquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.previous_page_number }}">&laquo;</a></li>\n        {% endif %}\n        <li class="page-item disabled"><span class="page-link">Strona {{ page_obj.number }} z {{ page_obj.paginator.num_pages }}</span></li>\n        {% if page_obj.has_next %}\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.next_page_number }}">&raquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.paginator.num_pages }}">&raquo;&raquo;</a></li>\n        {% endif %}\n    </ul>\n</nav>\n{% endif %}\n{% endblock %}\n'
FILES['clients/templates/clients/owner_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n\n<div class="form-card">\n    <form method="post">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Imie</label>\n                {{ form.first_name }}\n                {% if form.first_name.errors %}<div class="invalid-feedback-custom">{{ form.first_name.errors|first }}</div>{% endif %}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Nazwisko</label>\n                {{ form.last_name }}\n                {% if form.last_name.errors %}<div class="invalid-feedback-custom">{{ form.last_name.errors|first }}</div>{% endif %}\n            </div>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Telefon</label>\n            {{ form.phone }}\n            {% if form.phone.errors %}<div class="invalid-feedback-custom">{{ form.phone.errors|first }}</div>{% endif %}\n            <small class="text-muted">Format dowolny - system tylko ostrzeze, jesli numer wyglada niepoprawnie.</small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Email (opcjonalnie)</label>\n            {{ form.email }}\n            {% if form.email.errors %}<div class="invalid-feedback-custom">{{ form.email.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Notatki</label>\n            {{ form.notes }}\n        </div>\n\n        <hr>\n        <h6 class="mb-3"><i class="bi bi-person-plus"></i> Kontakt zastepczy (opcjonalnie)</h6>\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Imie i nazwisko</label>\n                {{ form.secondary_contact_name }}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Telefon</label>\n                {{ form.secondary_contact_phone }}\n            </div>\n        </div>\n\n        <hr>\n        <h6 class="mb-3"><i class="bi bi-shield-check"></i> RODO</h6>\n        <div class="form-check mb-2">\n            {{ form.rodo_consent }}\n            <label class="form-check-label" for="{{ form.rodo_consent.id_for_label }}">\n                Zgoda na przetwarzanie danych osobowych (RODO)\n            </label>\n        </div>\n        <div class="form-check mb-3">\n            {{ form.photo_consent }}\n            <label class="form-check-label" for="{{ form.photo_consent.id_for_label }}">\n                Zgoda na wykorzystanie zdjec psa (np. social media)\n            </label>\n        </div>\n        {% if owner and owner.rodo_consent_date %}\n            <p class="text-muted small">Zgoda RODO udzielona: {{ owner.rodo_consent_date|date:"d.m.Y" }}</p>\n        {% endif %}\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            <a href="{% url \'owner_list\' %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/owner_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ owner.full_name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-person-circle"></i> {{ owner.full_name }}</h1>\n    <div>\n        <a href="{% url \'owner_update\' owner.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'owner_delete\' owner.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'owner_list\' %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot\n        </a>\n    </div>\n</div>\n\n{% if not owner.rodo_consent %}\n<div class="alert alert-warning">\n    <i class="bi bi-exclamation-triangle-fill"></i> Brak zgody RODO od tego klienta.\n</div>\n{% endif %}\n\n<div class="row">\n    <div class="col-md-5">\n        <div class="detail-section mb-4">\n            <h5><i class="bi bi-card-text"></i> Dane kontaktowe</h5>\n            <p class="mb-1"><i class="bi bi-telephone"></i> <a href="tel:{{ owner.phone }}"><strong>{{ owner.phone }}</strong></a></p>\n            {% if owner.email %}\n                <p class="mb-1"><i class="bi bi-envelope"></i> <a href="mailto:{{ owner.email }}">{{ owner.email }}</a></p>\n            {% endif %}\n\n            {% if owner.secondary_contact_name or owner.secondary_contact_phone %}\n                <hr>\n                <h6><i class="bi bi-person-plus"></i> Kontakt zastepczy</h6>\n                {% if owner.secondary_contact_name %}<p class="mb-1">{{ owner.secondary_contact_name }}</p>{% endif %}\n                {% if owner.secondary_contact_phone %}<p class="mb-1"><a href="tel:{{ owner.secondary_contact_phone }}">{{ owner.secondary_contact_phone }}</a></p>{% endif %}\n            {% endif %}\n\n            <hr>\n            <p class="mb-1 small">\n                <i class="bi bi-shield-check"></i> Zgoda RODO:\n                {% if owner.rodo_consent %}\n                    <span class="text-success">Tak</span> ({{ owner.rodo_consent_date|date:"d.m.Y" }})\n                {% else %}\n                    <span class="text-danger">Nie</span>\n                {% endif %}\n            </p>\n            <p class="mb-1 small">\n                <i class="bi bi-camera"></i> Zgoda na zdjecia:\n                {% if owner.photo_consent %}<span class="text-success">Tak</span>{% else %}<span class="text-danger">Nie</span>{% endif %}\n            </p>\n\n            {% if owner.notes %}\n                <hr>\n                <h6>Notatki</h6>\n                <p>{{ owner.notes|linebreaks }}</p>\n            {% endif %}\n        </div>\n    </div>\n\n    <div class="col-md-7">\n        <div class="detail-section">\n            <div class="d-flex justify-content-between align-items-center mb-3">\n                <h5 class="mb-0"><i class="bi bi-suit-heart-fill"></i> Psy ({{ dogs.count }})</h5>\n                <a href="{% url \'dog_create_for_owner\' owner.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-plus-lg"></i> Dodaj psa\n                </a>\n            </div>\n            <div class="row">\n                {% for dog in dogs %}\n                <div class="col-md-6 mb-3">\n                    <div class="card exercise-card h-100">\n                        {% if dog.photo %}\n                            <img src="{{ dog.photo.url }}" class="card-img-top" style="height:150px;object-fit:cover;" alt="{{ dog.name }}">\n                        {% else %}\n                            <div class="card-img-placeholder" style="height:150px;"><i class="bi bi-image"></i></div>\n                        {% endif %}\n                        <div class="card-body">\n                            <h6 class="card-title mb-1">\n                                {{ dog.name }}\n                                {% if dog.training_status == \'paused\' %}\n                                    <span class="badge bg-warning text-dark">Wstrzymany</span>\n                                {% endif %}\n                            </h6>\n                            {% if dog.breed %}<p class="text-muted small mb-1">{{ dog.breed }}{% if dog.get_sex_display %} - {{ dog.get_sex_display }}{% endif %}</p>{% endif %}\n                            {% if dog.get_age_display %}<p class="text-muted small mb-0"><i class="bi bi-cake2"></i> {{ dog.get_age_display }}</p>{% endif %}\n                        </div>\n                        <div class="card-footer bg-white border-0 pb-2">\n                            <a href="{% url \'dog_detail\' dog.pk %}" class="btn btn-sm btn-primary">Szczegoly</a>\n                            <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-sm btn-outline-secondary"><i class="bi bi-pencil"></i></a>\n                        </div>\n                    </div>\n                </div>\n                {% empty %}\n                <div class="col-12">\n                    <p class="text-muted">Ten klient nie ma jeszcze zadnego psa w bazie.</p>\n                </div>\n                {% endfor %}\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/dog_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Psy{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1><i class="bi bi-suit-heart-fill" style="color: #D4AF37;"></i> Psy</h1>\n    <div>\n        <a href="{% url \'dog_export_csv\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-download"></i> Eksport CSV\n        </a>\n        <a href="{% url \'dog_archived_list\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-archive"></i> Archiwum\n        </a>\n        <a href="{% url \'dog_create\' %}" class="btn btn-primary">\n            <i class="bi bi-plus-lg"></i> Dodaj psa\n        </a>\n    </div>\n</div>\n\n<div class="search-bar">\n    <form method="get" class="row g-2 align-items-center">\n        <div class="col-md-10">\n            <div class="input-group">\n                <span class="input-group-text bg-white border-0"><i class="bi bi-search"></i></span>\n                <input type="text" name="q" class="form-control border-0" placeholder="Szukaj po imieniu psa, rasie lub wlascicielu..." value="{{ search_query }}">\n            </div>\n        </div>\n        <div class="col-md-2">\n            <button type="submit" class="btn btn-primary w-100"><i class="bi bi-funnel"></i> Szukaj</button>\n        </div>\n    </form>\n    {% if search_query %}\n        <div class="mt-2">\n            <a href="{% url \'dog_list\' %}" class="btn btn-sm btn-outline-secondary">\n                <i class="bi bi-x-circle"></i> Wyczysc\n            </a>\n        </div>\n    {% endif %}\n</div>\n\n<div class="row">\n    {% for dog in page_obj %}\n    <div class="col-md-4 mb-4">\n        <div class="card exercise-card">\n            {% if dog.photo %}\n                <img src="{{ dog.photo.url }}" class="card-img-top" alt="{{ dog.name }}">\n            {% else %}\n                <div class="card-img-placeholder"><i class="bi bi-image"></i></div>\n            {% endif %}\n            <div class="card-body">\n                <h5 class="card-title">\n                    {{ dog.name }}\n                    {% if dog.training_status == \'paused\' %}\n                        <span class="badge bg-warning text-dark">Wstrzymany</span>\n                    {% endif %}\n                </h5>\n                {% if dog.breed %}<p class="text-muted small mb-1">{{ dog.breed }}{% if dog.get_sex_display %} - {{ dog.get_sex_display }}{% endif %}</p>{% endif %}\n                {% if dog.get_age_display %}<p class="text-muted small mb-1"><i class="bi bi-cake2"></i> {{ dog.get_age_display }}</p>{% endif %}\n                <p class="small mb-0"><i class="bi bi-person"></i> <a href="{% url \'owner_detail\' dog.owner.pk %}">{{ dog.owner.full_name }}</a></p>\n            </div>\n            <div class="card-footer bg-white border-0 pb-3">\n                <a href="{% url \'dog_detail\' dog.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-eye"></i> Szczegoly\n                </a>\n                <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-sm btn-outline-secondary">\n                    <i class="bi bi-pencil"></i>\n                </a>\n                <a href="{% url \'dog_delete\' dog.pk %}" class="btn btn-sm btn-outline-danger">\n                    <i class="bi bi-archive"></i>\n                </a>\n            </div>\n        </div>\n    </div>\n    {% empty %}\n    <div class="col-12">\n        <div class="empty-state">\n            <i class="bi bi-inbox"></i>\n            <p class="mb-3">\n                {% if search_query %}\n                    Nie znaleziono psow spelniajacych kryteria.\n                {% else %}\n                    Brak psow w bazie.\n                {% endif %}\n            </p>\n        </div>\n    </div>\n    {% endfor %}\n</div>\n\n{% if page_obj.paginator.num_pages > 1 %}\n<nav class="d-flex justify-content-center mt-4">\n    <ul class="pagination">\n        {% if page_obj.has_previous %}\n            <li class="page-item"><a class="page-link" href="?page=1">&laquo;&laquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.previous_page_number }}">&laquo;</a></li>\n        {% endif %}\n        <li class="page-item disabled"><span class="page-link">Strona {{ page_obj.number }} z {{ page_obj.paginator.num_pages }}</span></li>\n        {% if page_obj.has_next %}\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.next_page_number }}">&raquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.paginator.num_pages }}">&raquo;&raquo;</a></li>\n        {% endif %}\n    </ul>\n</nav>\n{% endif %}\n{% endblock %}\n'
FILES['clients/templates/clients/dog_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n{% if fixed_owner %}\n<p class="text-muted">Wlasciciel: <strong>{{ fixed_owner.full_name }}</strong></p>\n{% endif %}\n\n<div class="form-card">\n    <form method="post" enctype="multipart/form-data">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        {% if not fixed_owner %}\n        <div class="mb-3">\n            <label class="form-label">Wlasciciel</label>\n            {{ form.owner }}\n            {% if form.owner.errors %}<div class="invalid-feedback-custom">{{ form.owner.errors|first }}</div>{% endif %}\n        </div>\n        {% else %}\n            {{ form.owner }}\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Imie psa</label>\n            {{ form.name }}\n            {% if form.name.errors %}<div class="invalid-feedback-custom">{{ form.name.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Rasa (opcjonalnie)</label>\n                {{ form.breed }}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Plec (opcjonalnie)</label>\n                {{ form.sex }}\n            </div>\n        </div>\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Data urodzenia (opcjonalnie)</label>\n                {{ form.birth_date }}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Waga w kg (opcjonalnie)</label>\n                {{ form.weight_kg }}\n            </div>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Status treningowy</label>\n            {{ form.training_status }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Informacje zdrowotne / przeciwwskazania</label>\n            {{ form.health_notes }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Notatki trenera</label>\n            {{ form.trainer_notes }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-image"></i> Zdjecie (opcjonalnie)</label>\n            {{ form.photo }}\n            {% if form.photo.errors %}<div class="invalid-feedback-custom">{{ form.photo.errors|first }}</div>{% endif %}\n            {% if dog and dog.photo %}\n                <div class="mt-2">\n                    <img src="{{ dog.photo.url }}" style="max-width:150px;border-radius:10px;" alt="{{ dog.name }}">\n                </div>\n            {% endif %}\n        </div>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            {% if fixed_owner %}\n                <a href="{% url \'owner_detail\' fixed_owner.pk %}" class="btn btn-secondary">Anuluj</a>\n            {% else %}\n                <a href="{% url \'dog_list\' %}" class="btn btn-secondary">Anuluj</a>\n            {% endif %}\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/dog_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ dog.name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-suit-heart-fill"></i> {{ dog.name }}\n        {% if dog.training_status == \'paused\' %}\n            <span class="badge bg-warning text-dark">Trening wstrzymany</span>\n        {% endif %}\n    </h1>\n    <div>\n        <form method="post" action="{% url \'dog_toggle_training_status\' dog.pk %}" style="display:inline;">\n            {% csrf_token %}\n            {% if dog.training_status == \'paused\' %}\n                <button type="submit" class="btn btn-outline-success">\n                    <i class="bi bi-play-circle"></i> Przywroc trening\n                </button>\n            {% else %}\n                <button type="submit" class="btn btn-outline-warning">\n                    <i class="bi bi-pause-circle"></i> Wstrzymaj trening\n                </button>\n            {% endif %}\n        </form>\n        <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'dog_delete\' dog.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'owner_detail\' dog.owner.pk %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot do wlasciciela\n        </a>\n    </div>\n</div>\n\n<div class="row">\n    <div class="col-md-4">\n        {% if dog.photo %}\n            <img src="{{ dog.photo.url }}" class="img-fluid rounded mb-3" alt="{{ dog.name }}">\n        {% else %}\n            <div class="card-img-placeholder mb-3" style="height:250px;"><i class="bi bi-image"></i></div>\n        {% endif %}\n    </div>\n    <div class="col-md-8">\n        <div class="detail-section">\n            <p><i class="bi bi-person"></i> Wlasciciel: <a href="{% url \'owner_detail\' dog.owner.pk %}">{{ dog.owner.full_name }}</a>\n                (<a href="tel:{{ dog.owner.phone }}">{{ dog.owner.phone }}</a>)\n            </p>\n            {% if dog.breed %}<p><i class="bi bi-tag"></i> Rasa: {{ dog.breed }}</p>{% endif %}\n            {% if dog.get_sex_display %}<p><i class="bi bi-gender-ambiguous"></i> Plec: {{ dog.get_sex_display }}</p>{% endif %}\n            {% if dog.get_age_display %}<p><i class="bi bi-cake2"></i> Wiek: {{ dog.get_age_display }}</p>{% endif %}\n            {% if dog.weight_kg %}<p><i class="bi bi-speedometer2"></i> Waga: {{ dog.weight_kg }} kg</p>{% endif %}\n\n            {% if dog.health_notes %}\n                <div class="alert alert-warning mt-3">\n                    <i class="bi bi-exclamation-triangle-fill"></i>\n                    <strong>Informacje zdrowotne:</strong> {{ dog.health_notes|linebreaks }}\n                </div>\n            {% endif %}\n\n            {% if dog.trainer_notes %}\n                <hr>\n                <h6>Notatki trenera</h6>\n                <p>{{ dog.trainer_notes|linebreaks }}</p>\n            {% endif %}\n        </div>\n    </div>\n</div>\n{% endblock %}\n'


def main():
    print("=" * 70)
    print("DogFitness - _update7.py - ROZSZERZENIE MODULU: Klienci")
    print("=" * 70)

    if not os.path.exists(os.path.join(BASE_DIR, "manage.py")):
        print("!! UWAGA: nie znaleziono 'manage.py' w tym folderze.")
        sys.exit(1)

    if not os.path.exists(os.path.join(BASE_DIR, "clients")):
        print("!! UWAGA: nie znaleziono folderu 'clients/'.")
        print("   Ten skrypt wymaga wczesniej zastosowanego _update6.py!")
        answer = input("   Czy chcesz kontynuowac mimo to? (tak/nie): ").strip().lower()
        if answer not in ("tak", "t", "yes", "y"):
            print("Przerwano.")
            sys.exit(1)

    backed_up_any = False

    for rel_path, content in FILES.items():
        full_path = os.path.join(BASE_DIR, rel_path.replace("/", os.sep))
        dir_path = os.path.dirname(full_path)

        if not os.path.exists(dir_path):
            os.makedirs(dir_path, exist_ok=True)
            print(f"[+] Utworzono folder: {dir_path}")

        if os.path.exists(full_path):
            backup_target = os.path.join(BACKUP_DIR, rel_path.replace("/", os.sep))
            os.makedirs(os.path.dirname(backup_target), exist_ok=True)
            shutil.copy2(full_path, backup_target)
            backed_up_any = True

        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[OK] Zapisano: {rel_path}")

    print("-" * 70)
    if backed_up_any:
        print(f"Kopie zapasowe nadpisanych plikow zapisano w:")
        print(f"  {BACKUP_DIR}")
    else:
        print("Nie bylo plikow do zbackupowania (wszystkie byly nowe).")

    print("-" * 70)
    print("GOTOWE! Nastepne kroki (WYMAGANE):")
    print("  1. python manage.py makemigrations clients")
    print("  2. python manage.py migrate")
    print("  3. python manage.py runserver")
    print("  4. Wejdz na /clients/ (zalogowany) - zobacz nowe pola RODO,")
    print("     status treningowy psa, kontakt zastepczy, eksport CSV")
    print("=" * 70)


if __name__ == "__main__":
    main()
